(2193, '27022512551822', 'VP/M/24/11/030', 394, '66', '{\"name_of_consignee\":\"M\\/s. Mikuni India Ltd., Neemrana, Alwar (RJ)\",\"salutation\":\"Mr\",\"name_of_commodity\":\"Sensor Assy, Stepperr Motor Assy & Throttle Body Assy\",\"address\":\"Alwar, Rajasthan\",\"available_at_location\":\"yes\",\"cause_loss\":\"During transit the consignment carrying vehicle faced lots of bump\\/ ditches and jerks and jolts were occurred due to which the consignment inside the vehicle got damaged or the consignment got damaged due to mishandling by the transporter. The same was delivered to consignee in damaged condition.\",\"contact_person_name\":\"Arun Mehra\",\"invoices\":[{\"invoicenumber\":\"MID24-186\",\"invoicedate\":\"2024-09-30\"}],\"case_reference\":\"VP\\/M\\/24\\/11\\/030\",\"contact_person_mobile\":\"9953533450\"}', '{\"policy_by\":\"IFFCO TOKIO GENERAL INSURANCE CO. LTD.\",\"appoint_by\":\"IFFCO TOKIO GENERAL INSURANCE CO. LTD.\",\"payment_by\":\"IFFCO TOKIO GENERAL INSURANCE CO. LTD.\",\"selected_policy_vendor_id\":\"223\",\"policy_branch\":\"Iffcor House, Second Floor, 34 Nehru Place, New Delhi - 110019, New Delhi ,Delhi - 110019\",\"policy_user\":\"Mr. Jatin \",\"policy_mobile\":\"+918700560141\",\"policybillingto\":\"NA\",\"selected_appointment_vendor_id\":\"223\",\"appointment_gst\":\"07AAACI7573H1ZE\",\"appointment_branch_name\":\"Iffcor House, Second Floor, 34 Nehru Place, New Delhi - 110019, New Delhi ,Delhi - 110019\",\"appointment_user_name\":\"Mr. Jatin \",\"appointment_mobile_num\":\"+918700560141\",\"appointbillingto\":\"NA\",\"selected_payment_vendor_id\":\"223\",\"payment_gst\":\"07AAACI7573H1ZE\",\"payment_branch_name\":\"Iffcor House, Second Floor, 34 Nehru Place, New Delhi - 110019, New Delhi ,Delhi - 110019\",\"payment_user_name\":\"Mr. Jatin \",\"payment_mobile_num\":\"+918700560141\",\"paymentbillingto\":\"NA\",\"case_reference\":\"VP\\/M\\/24\\/11\\/030\",\"date_of_report\":\"2025-02-27\",\"claim_no\":\"23403\",\"insured_name\":\"M\\/s. Mikuni I