INSERT INTO `claims_lor` (`id`, `department`, `description`) VALUES
(1, 'Motor', 'Registration Certificate of the vehicle.'),
(2, 'Motor', 'Copy of FIR, if in language other than English/Hindi, the same may please be translated to either of the language.'),
(3, 'Motor', 'Copy of intimation letter to insurance company,'),
(4, 'Motor', 'Any evidence to prove that the vehicle was in well upgraded condition,'),
(5, 'Motor', 'All the original keys of the vehicle,'),
(6, 'Motor', 'Letter to RTO and NCRB intimating them about the theft of the vehicle alongwith NCRB report/confirmation,'),
(7, 'Motor', 'Up-to-date finance statement of the vehicle, if on hire-purchase agreement or NOC if loan has been repaid.'),
(8, 'Motor', 'Final Report/Untrace Report,'),
(9, 'Motor', 'Purchase invoice and payment proof,'),
(10, 'Motor', 'Previous insurance/s,'),
(11, 'Motor', 'Pre-insurance inspection report, if any.'),
(12, 'Motor', 'Map/Site plan of the place from where the vehicle was stolen,'),
(13, 'Motor', 'Personal statement of the insured,'),
(14, 'Motor', 'Spot/place of theft photographs,'),
(15, 'Motor', 'Vehicle particulars,'),
(16, 'Motor', 'Police verification,'),
(17, 'Motor', 'Chowkidar statement,'),
(18, 'Motor', 'Road challan/GR,'),
(19, 'Motor', 'Photo ID of Insured,'),
(20, 'Motor', 'Bank Account Number of Insured.'),
(21, 'Motor', 'Copy of Adhaar Card,'),
(22, 'Motor', 'Survey fee for the bill enclosed, the same stands reimbursable with tenable claim amount by your insurers,'),
(23, 'Motor', 'Spot report, if any,'),
(24, 'Motor', 'Repair estimates giving detailed brake up of each item estimated for repairs/replacement'),
(25, 'Motor', 'Fire Brigade Report issued by the concerned Fire Services,'),
(26, 'Motor', 'Copy of FIR/Daily Diary issued by the Police, along with duly stamped copy of the initial intimation given to the police,'),
(27, 'Motor', 'New Insurance, valid as on date of loss,'),
(28, 'Motor', 'Driving license of the person who had last driven the vehicle to the spot of loss / damage,'),
(29, 'Motor', 'Claim form duly completed, and, signed by the insured, in the case of a firm, please send it duly stamped by authorized signatory.'),
(30, 'Motor', 'Running proof as on date of loss / damage of the vehicle,'),
(31, 'Motor', 'Statement of Neighbour/s confirming the circumstances of loss,'),
(32, 'Motor', 'Fitness of vehicle,'),
(33, 'Motor', 'Copy of PAN Card of insured / Firm,'),
(34, 'Motor', 'Permit of vehicle,'),
(35, 'Motor', 'Salvage Value Offer - Please give your best offer, beyond which if realizable, to insurers, will be able to open auction/sell the salvaged goods in as it is condition.'),
